// ===================================================================
// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Car row store: row per URL, history, gone marks
// Flo: hash the phone with a local salt > cluster id from make, model, year, province, km band > upsert > price history row only when the price changed > gone by 404/410, by a sold notice, or by not being seen for carz_dead_days
// I/O: open Db + Car (caller) > Svre; raw phone digits live in the row only until purge, the hash stays; individual seller names are never stored
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig"); const typz = @import("pa-carz-type.zig"); const norm = @import("pa-carz-norm.zig"); const fail = @import("ru-fail-over.zig");
const Carz = typz.Carz;
pub const Svre = enum { news, chan, same };
const NAMS = [_][]const u8{ "site", "lidz", "clsz", "titl", "make", "modl", "trim", "year", "body", "seat", "door", "orig", "cond", "powr", "fuel", "engn", "gear", "driv", "colx", "coli", "kmzz", "owns", "pric", "prov", "dist", "post", "sell", "shop", "phsh", "phon", "text", "xtra", "hexz", "pver", "clus" };
const SQLU = blk: { @setEvalBranchQuota(200000); var cols: []const u8 = "urlz"; var vals: []const u8 = "?1"; var upds: []const u8 = ""; for (NAMS, 0..) |namz, indx| { cols = cols ++ "," ++ namz; vals = vals ++ std.fmt.comptimePrint(",?{d}", .{indx + 2}); upds = upds ++ (if (indx > 0) "," else "") ++ (if (std.mem.eql(u8, namz, "pric")) "pric=CASE WHEN excluded.pric>0 THEN excluded.pric ELSE carz.pric END" else namz ++ "=excluded." ++ namz); } break :blk "INSERT INTO carz(" ++ cols ++ ",fors,lasz,stat,gone,grsn) VALUES(" ++ vals ++ std.fmt.comptimePrint(",?{d},?{d},0,0,'') ON CONFLICT(urlz) DO UPDATE SET ", .{ NAMS.len + 2, NAMS.len + 2 }) ++ upds ++ ",lasz=MAX(carz.lasz,excluded.lasz),stat=0,gone=0,grsn='';"; };
pub const Stor = struct { dbzz: *sqli.Dbzz, salt: i64 };
const Bind = struct { stmt: *sqli.Stmt, indx: c_int = 1, fn txtz(self: *Bind, text: []const u8) !void { try self.stmt.bindText(self.indx, text); self.indx += 1; } fn numz(self: *Bind, valu: i64) !void { try self.stmt.bindIntz(self.indx, valu); self.indx += 1; } };
pub fn storOpen(dbzz: *sqli.Dbzz, nowz: i64) !Stor { var salt = try fail.flagGetz(dbzz, "carz_salt"); if (salt == 0) { salt = @bitCast(std.hash.Wyhash.hash(0x5eed, std.mem.asBytes(&nowz))); if (salt == 0) salt = 1; try fail.flagSetz(dbzz, "carz_salt", salt); } return .{ .dbzz = dbzz, .salt = salt }; }
fn hashSixt(salt: i64, text: []const u8, buff: *[16]u8) []const u8 { const code = std.hash.Wyhash.hash(@bitCast(salt), text); return std.fmt.bufPrint(buff, "{x:0>16}", .{code}) catch ""; }
fn clusBase(carz: Carz, phnz: []const u8, full: bool, salt: i64, buff: *[16]u8) []const u8 { if (carz.make.len == 0 or carz.year == 0 or std.mem.eql(u8, carz.cond, "new") or std.mem.eql(u8, carz.sell, "buyer")) return ""; var tmpz: [256]u8 = undefined; const seed = std.fmt.bufPrint(&tmpz, "{s}|{s}|{d}|{s}|{s}|{s}|{s}", .{ carz.make, carz.modl, carz.year, carz.prov, carz.gear, carz.powr, if (full) phnz else "" }) catch return ""; var lowz: [256]u8 = undefined; for (seed, 0..) |bytz, indx| lowz[indx] = std.ascii.toLower(bytz); return hashSixt(salt, lowz[0..seed.len], buff); }
pub fn clusFind(self: *Stor, carz: Carz, phnz: []const u8, full: bool, buff: *[40]u8) ![]const u8 { var basz: [16]u8 = undefined; const base = clusBase(carz, phnz, full, self.salt, &basz); if (base.len == 0) return ""; if (carz.kmzz >= 0) { var lozz: [24]u8 = undefined; var hizz: [24]u8 = undefined; const lows = std.fmt.bufPrint(&lozz, "{s}.", .{base}) catch return ""; const higs = std.fmt.bufPrint(&hizz, "{s}/", .{base}) catch return ""; var selz = try self.dbzz.prep("SELECT clus FROM carz WHERE clus>=?1 AND clus<?2 AND kmzz>=0 AND abs(kmzz-?3)<=3000 LIMIT 1;"); defer selz.fini(); try selz.bindText(1, lows); try selz.bindText(2, higs); try selz.bindIntz(3, carz.kmzz); if (try selz.step()) { const gotz = selz.colzText(0); const lenz = @min(gotz.len, buff.len); @memcpy(buff[0..lenz], gotz[0..lenz]); return buff[0..lenz]; } return std.fmt.bufPrint(buff, "{s}.{d}", .{ base, @divTrunc(carz.kmzz, 100) }) catch ""; } return std.fmt.bufPrint(buff, "{s}.x", .{base}) catch ""; }
pub fn carzSave(self: *Stor, carz: Carz, hexz: []const u8, seen: i64) !Svre { var pbuf: [16]u8 = undefined; const phnz = norm.normPhon(carz.phon, &pbuf); var hbuf: [16]u8 = undefined; const phsh: []const u8 = if (phnz.digi.len >= 7) hashSixt(self.salt, phnz.digi, &hbuf) else ""; var cbuf: [40]u8 = undefined; const clus = try clusFind(self, carz, phnz.digi, phnz.full, &cbuf);
    var oldp: i64 = -1; var oldh: [64]u8 = undefined; var oldn: usize = 0; { var selz = try self.dbzz.prep("SELECT pric,hexz FROM carz WHERE urlz=?1;"); defer selz.fini(); try selz.bindText(1, carz.urlz); if (try selz.step()) { oldp = selz.colzIntz(0); const hzzz = selz.colzText(1); oldn = @min(hzzz.len, oldh.len); @memcpy(oldh[0..oldn], hzzz[0..oldn]); } }
    var stmt = try self.dbzz.prep(SQLU); defer stmt.fini(); var bndz: Bind = .{ .stmt = &stmt }; try bndz.txtz(carz.urlz); try bndz.txtz(carz.site); try bndz.txtz(carz.lidz); try bndz.txtz(carz.clsz); try bndz.txtz(carz.titl); try bndz.txtz(carz.make); try bndz.txtz(carz.modl); try bndz.txtz(carz.trim); try bndz.numz(carz.year); try bndz.txtz(carz.body); try bndz.numz(carz.seat); try bndz.numz(carz.door); try bndz.txtz(carz.orig); try bndz.txtz(carz.cond); try bndz.txtz(carz.powr); try bndz.txtz(carz.fuel); try bndz.txtz(carz.engn); try bndz.txtz(carz.gear); try bndz.txtz(carz.driv); try bndz.txtz(carz.colx); try bndz.txtz(carz.coli); try bndz.numz(carz.kmzz); try bndz.numz(carz.owns); try bndz.numz(carz.pric); try bndz.txtz(carz.prov); try bndz.txtz(carz.dist); try bndz.numz(carz.post); try bndz.txtz(carz.sell); try bndz.txtz(carz.shop); try bndz.txtz(phsh); try bndz.txtz(phnz.digi); try bndz.txtz(carz.text); try bndz.txtz(carz.xtra); try bndz.txtz(hexz); try bndz.numz(typz.VERS); try bndz.txtz(clus); try bndz.numz(seen); _ = try stmt.step();
    if (carz.pric > 0 and carz.pric != oldp) { var hisz = try self.dbzz.prep("INSERT OR IGNORE INTO carp(urlz,timz,pric) VALUES(?1,?2,?3);"); defer hisz.fini(); try hisz.bindText(1, carz.urlz); try hisz.bindIntz(2, seen); try hisz.bindIntz(3, carz.pric); _ = try hisz.step(); } if (oldp < 0) return .news; return if (std.mem.eql(u8, oldh[0..oldn], hexz)) .same else .chan; }
pub fn goneMark(self: *Stor, urlz: []const u8, nowz: i64, whyz: []const u8) !void { var stmt = try self.dbzz.prep("UPDATE carz SET stat=1,gone=?2,grsn=?3 WHERE urlz=?1 AND stat=0;"); defer stmt.fini(); try stmt.bindText(1, urlz); try stmt.bindIntz(2, nowz); try stmt.bindText(3, whyz); _ = try stmt.step(); }
pub fn goneHttp(self: *Stor, nowz: i64) !u32 { var stmt = try self.dbzz.prep("UPDATE carz SET stat=1,gone=?1,grsn='http' WHERE stat=0 AND urlz IN (SELECT urlz FROM page WHERE code IN (404,410));"); defer stmt.fini(); try stmt.bindIntz(1, nowz); _ = try stmt.step(); return @intCast(self.dbzz.cha2()); }
pub fn goneDead(self: *Stor, nowz: i64, deadMill: i64) !u32 { var stmt = try self.dbzz.prep("UPDATE carz SET stat=1,gone=?1,grsn='vani' WHERE stat=0 AND lasz<?2;"); defer stmt.fini(); try stmt.bindIntz(1, nowz); try stmt.bindIntz(2, nowz - deadMill); _ = try stmt.step(); return @intCast(self.dbzz.cha2()); }
